package com.vibeguard.samples.roles; import jakarta.validation.Valid; import jakarta.validation.constraints.NotBlank; import java.util.*; import java.util.concurrent.ConcurrentHashMap; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*; /** Limits authorization changes to trusted role administrators. */ @RestController @RequestMapping("/internal/roles") public class RoleController { private final Map<String,Set<String>> roles=new ConcurrentHashMap<>(); @Value("${ROLE_ADMIN_KEY:}") private String adminKey; @PostMapping("/{userId}") public ResponseEntity<Void> assign(@RequestHeader("X-Role-Admin-Key") String key,@PathVariable String userId,@Valid @RequestBody Request request){if(!allowed(key))return ResponseEntity.status(401).build();roles.computeIfAbsent(userId,ignored->ConcurrentHashMap.newKeySet()).add(request.role());return ResponseEntity.noContent().build();}@DeleteMapping("/{userId}/{role}") public ResponseEntity<Void> remove(@RequestHeader("X-Role-Admin-Key") String key,@PathVariable String userId,@PathVariable String role){if(!allowed(key))return ResponseEntity.status(401).build();roles.getOrDefault(userId,Set.of()).remove(role);return ResponseEntity.noContent().build();}@GetMapping("/{userId}") public ResponseEntity<Set<String>> list(@RequestHeader("X-Role-Admin-Key") String key,@PathVariable String userId){return allowed(key)?ResponseEntity.ok(Set.copyOf(roles.getOrDefault(userId,Set.of()))):ResponseEntity.status(401).build();}private boolean allowed(String key){return !adminKey.isBlank()&&adminKey.equals(key);}record Request(@NotBlank String role){} }
